"""Products and the catalog that holds them."""

from __future__ import annotations

from collections.abc import Iterable, Iterator
from dataclasses import dataclass

from shop.errors import DuplicateProductError, UnknownProductError


@dataclass(frozen=True)
class Product:
    sku: str
    name: str
    price_cents: int
    category: str = "general"
    taxable: bool = True
    weight_g: int = 0

    def __post_init__(self) -> None:
        if not self.sku:
            raise ValueError("sku must not be empty")
        if self.price_cents < 0:
            raise ValueError("price must not be negative")
        if self.weight_g < 0:
            raise ValueError("weight must not be negative")


class Catalog:
    def __init__(self, products: Iterable[Product] = ()) -> None:
        self._products: dict[str, Product] = {}
        for product in products:
            self.add(product)

    def add(self, product: Product) -> None:
        if product.sku in self._products:
            raise DuplicateProductError(product.sku)
        self._products[product.sku] = product

    def get(self, sku: str) -> Product:
        try:
            return self._products[sku]
        except KeyError:
            raise UnknownProductError(sku) from None

    def remove(self, sku: str) -> Product:
        product = self.get(sku)
        del self._products[sku]
        return product

    def skus(self) -> list[str]:
        return sorted(self._products)

    def by_category(self, category: str) -> list[Product]:
        return [p for p in self._sorted() if p.category == category]

    def categories(self) -> list[str]:
        return sorted({p.category for p in self._products.values()})

    def search(self, text: str) -> list[Product]:
        """Products whose name contains ``text``, ordered by SKU."""
        return [p for p in self._sorted() if text in p.name]

    def _sorted(self) -> list[Product]:
        return [self._products[sku] for sku in sorted(self._products)]

    def __contains__(self, sku: object) -> bool:
        return sku in self._products

    def __len__(self) -> int:
        return len(self._products)

    def __iter__(self) -> Iterator[Product]:
        return iter(self._sorted())
"""Exception types shared by every module."""


class ShopError(Exception):
    """Base class for all errors raised by this package."""


class UnknownProductError(ShopError):
    """A SKU is not in the catalog."""


class DuplicateProductError(ShopError):
    """A SKU is already in the catalog."""


class OutOfStockError(ShopError):
    """Not enough units in stock."""


class InvalidOrderError(ShopError):
    """The order is empty, malformed, or in the wrong state for the request."""


class InvalidCouponError(ShopError):
    """The coupon code is not known."""
"""Bulk discounts, coupons, tax and shipping. All amounts are integer cents."""

from __future__ import annotations

from collections.abc import Iterable
from dataclasses import dataclass
from decimal import Decimal
from typing import Protocol

from shop.errors import InvalidCouponError
from shop.money import round_half_up

# (minimum quantity, percent off the line), checked from the largest tier down.
BULK_TIERS: tuple[tuple[int, int], ...] = ((10, 10), (5, 5))

# code -> (kind, value). "percent" is a whole percent, "fixed" is cents.
COUPONS: dict[str, tuple[str, int]] = {
    "SAVE10": ("percent", 10),
    "FIVEOFF": ("fixed", 500),
}

TAX_RATES: dict[str, Decimal] = {
    "general": Decimal("0.08"),
    "electronics": Decimal("0.10"),
    "grocery": Decimal("0"),
}
DEFAULT_TAX_RATE = Decimal("0.08")

FREE_SHIPPING_AT_CENTS = 5000
BASE_SHIPPING_CENTS = 500
PER_KG_SHIPPING_CENTS = 100


class PricedLine(Protocol):
    unit_price_cents: int
    qty: int
    category: str
    taxable: bool
    weight_g: int


@dataclass(frozen=True)
class Totals:
    subtotal_cents: int
    discount_cents: int
    tax_cents: int
    shipping_cents: int
    total_cents: int


def bulk_discount_percent(qty: int) -> int:
    for min_qty, percent in BULK_TIERS:
        if qty >= min_qty:
            return percent
    return 0


def apply_percent(cents: int, percent: int) -> int:
    """The amount that ``percent`` percent of ``cents`` comes to, rounded half up."""
    return round_half_up(Decimal(cents) * Decimal(percent) / 100)


def line_total(unit_price_cents: int, qty: int) -> int:
    """Price of ``qty`` units after the bulk discount."""
    gross = unit_price_cents * qty
    return gross - apply_percent(gross, bulk_discount_percent(qty))


def coupon_discount(subtotal_cents: int, code: str | None) -> int:
    """Cents off for ``code``. Never more than the subtotal."""
    if code is None:
        return 0
    if code not in COUPONS:
        raise InvalidCouponError(code)
    kind, value = COUPONS[code]
    off = apply_percent(subtotal_cents, value) if kind == "percent" else value
    return min(off, subtotal_cents)


def tax_rate(category: str) -> Decimal:
    return TAX_RATES.get(category, DEFAULT_TAX_RATE)


def shipping_cents(subtotal_cents: int, weight_g: int) -> int:
    if subtotal_cents <= 0:
        return 0
    if subtotal_cents >= FREE_SHIPPING_AT_CENTS:
        return 0
    return BASE_SHIPPING_CENTS + (weight_g // 1000) * PER_KG_SHIPPING_CENTS


def price_lines(lines: Iterable[PricedLine], coupon: str | None = None) -> Totals:
    """Price an order. Tax is charged on discounted line totals, before any coupon."""
    lines = list(lines)
    subtotal = 0
    weight = 0
    taxable_by_category: dict[str, int] = {}
    for line in lines:
        total = line_total(line.unit_price_cents, line.qty)
        subtotal += total
        weight += line.weight_g * line.qty
        if line.taxable:
            taxable_by_category[line.category] = taxable_by_category.get(line.category, 0) + total
    discount = coupon_discount(subtotal, coupon)
    tax = sum(
        round_half_up(Decimal(base) * tax_rate(category))
        for category, base in taxable_by_category.items()
    )
    shipping = shipping_cents(subtotal - discount, weight)
    return Totals(
        subtotal_cents=subtotal,
        discount_cents=discount,
        tax_cents=tax,
        shipping_cents=shipping,
        total_cents=subtotal - discount + tax + shipping,
    )
"""Placing and cancelling orders against a catalog and an inventory."""

from __future__ import annotations

from collections.abc import Mapping
from dataclasses import dataclass, field

from shop import pricing
from shop.catalog import Catalog
from shop.errors import InvalidOrderError, OutOfStockError
from shop.inventory import Inventory


@dataclass(frozen=True)
class OrderLine:
    sku: str
    name: str
    unit_price_cents: int
    qty: int
    category: str
    taxable: bool
    weight_g: int

    @property
    def line_total_cents(self) -> int:
        return pricing.line_total(self.unit_price_cents, self.qty)


@dataclass
class Order:
    id: int
    lines: list[OrderLine]
    coupon: str | None
    totals: pricing.Totals
    status: str = field(default="placed")  # "placed" or "cancelled"


class OrderBook:
    def __init__(self, catalog: Catalog, inventory: Inventory) -> None:
        self._catalog = catalog
        self._inventory = inventory
        self._orders: dict[int, Order] = {}
        self._next_id = 1

    def place_order(self, items: Mapping[str, int], coupon: str | None = None) -> Order:
        """Reserve stock for ``items`` (sku -> qty) and record the order.

        Either every line is fulfilled or nothing changes.
        """
        if not items:
            raise InvalidOrderError("order has no items")
        for sku, qty in items.items():
            if not isinstance(qty, int) or qty <= 0:
                raise InvalidOrderError(f"bad quantity for {sku}: {qty!r}")
        lines = []
        for sku in sorted(items):
            product = self._catalog.get(sku)
            lines.append(
                OrderLine(
                    sku=sku,
                    name=product.name,
                    unit_price_cents=product.price_cents,
                    qty=items[sku],
                    category=product.category,
                    taxable=product.taxable,
                    weight_g=product.weight_g,
                )
            )
        totals = pricing.price_lines(lines, coupon)  # validates the coupon before stock moves
        for line in lines:
            if not self._inventory.can_fulfill(line.sku, line.qty):
                raise OutOfStockError(f"{line.sku}: need {line.qty}")
        for line in lines:
            self._inventory.remove_stock(line.sku, line.qty)
        order = Order(id=self._next_id, lines=lines, coupon=coupon, totals=totals)
        self._orders[order.id] = order
        self._next_id += 1
        return order

    def get(self, order_id: int) -> Order:
        try:
            return self._orders[order_id]
        except KeyError:
            raise InvalidOrderError(f"unknown order {order_id}") from None

    def cancel(self, order_id: int) -> Order:
        order = self.get(order_id)
        if order.status != "placed":
            raise InvalidOrderError(f"order {order_id} is {order.status}")
        for line in order.lines:
            self._inventory.add_stock(line.sku, line.qty)
        order.status = "cancelled"
        return order

    def orders(self, status: str | None = None) -> list[Order]:
        found = [o for o in self._orders.values() if status is None or o.status == status]
        return sorted(found, key=lambda o: o.id)

